program_text='''from collections import Counter


def transform(grid):
    """Complete the outer frame and any long horizontal divider of a pattern."""
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    if not points:
        return [row[:] for row in grid]

    r0 = min(r for r, _ in points)
    r1 = max(r for r, _ in points)
    c0 = min(c for _, c in points)
    c1 = max(c for _, c in points)
    result = [row[:] for row in grid]

    # Close the perimeter of the foreground bounding box.
    for c in range(c0, c1 + 1):
        if result[r0][c] == background:
            result[r0][c] = 2
        if result[r1][c] == background:
            result[r1][c] = 2
    for r in range(r0, r1 + 1):
        if result[r][c0] == background:
            result[r][c0] = 2
        if result[r][c1] == background:
            result[r][c1] = 2

    # Rows with at least three foreground cells form horizontal dividers.
    for r in range(r0 + 1, r1):
        if sum(grid[r][c] != background for c in range(c0, c1 + 1)) >= 3:
            for c in range(c0, c1 + 1):
                if result[r][c] == background:
                    result[r][c] = 2
    return result
'''
